import { expect, expectStatus, test } from "../../fixtures";

test(
  "An insurance expiry date that cannot be parsed is extracted as null with low confidence",
  { tag: "@DOC-03" },
  async ({ apiAs, factory }) => {
    // Arrange
    const member = await apiAs("member");
    const vendor = await factory.vendor();
    expect(vendor.status).toBe("draft");
    // samples/insurance_certificate_unparseable.txt contains "Expiry Date: next spring".
    const document = await factory.upload(vendor.id, "insurance_certificate", "insurance_certificate_unparseable.txt");

    // Act: wait for background processing to finish
    await expect
      .poll(
        async () =>
          (await expectStatus<{ status: string }>(await member.get(`/api/documents/${document.id}`), 200)).status,
        { message: "processing finishes for the insurance certificate", timeout: 30_000 },
      )
      .toBe("extracted");

    // Assert
    const extraction = await expectStatus<{
      fields: Record<string, { value: string | null; confidence: number }>;
    }>(await member.get(`/api/documents/${document.id}/extraction`), 200);
    const expiry = extraction.fields.expiry_date;
    expect(expiry, `expiry_date is among ${Object.keys(extraction.fields).join(", ")}`).toBeDefined();
    expect(expiry.value).toBeNull();
    expect(expiry.confidence).toBeLessThan(0.5);
  },
);
